// Draft's big category list: 200 more, in eight groups. categories.js adds
// them to the first 16. Each is written as one line of items split on " | ",
// and its id comes from its name.
//
// A game only takes 10 items from a category (5 picks each), so a list
// needs at least 10; most have 20-25 so two games in the same category
// rarely look alike.

const C = (name, items) => ({
  id: name.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""),
  name,
  items: items.split(" | ").map((s) => s.trim()).filter(Boolean),
});

